{
  "findings": [
    {
      "check_id": "CKV2_AZURE_31",
      "title": "Subnet missing Network Security Group (NSG) association",
      "resource": "azurerm_subnet.data_subnet",
      "severity": "MEDIUM",
      "explanation": "The subnet 'data_subnet' is not associated with a Network Security Group. Without an NSG, traffic to and from resources in this subnet is unrestricted by default security rules, which violates the principle of least privilege and HIPAA network segmentation requirements."
    }
  ],
  "patched_code": "resource "azurerm_network_security_group" "data_nsg" {
  name                = "healthcare-patient-portal-data-nsg"
  location            = azurerm_resource_group.healthcare_portal.location
  resource_group_name = azurerm_resource_group.healthcare_portal.name
}

resource "azurerm_subnet_network_security_group_association" "data_subnet_nsg_assoc" {
  subnet_id                 = azurerm_subnet.data_subnet.id
  network_security_group_id = azurerm_network_security_group.data_nsg.id
}

resource "azurerm_subnet" "data_subnet" {
  name                 = "healthcare-patient-portal-with-hipaa-compliance-subnet-data"
  resource_group_name  = azurerm_resource_group.healthcare_portal.name
  virtual_network_name = azurerm_virtual_network.healthcare_vnet.name
  address_prefixes     = ["10.0.3.0/24"]
}",
  "fix_summary": "Added an `azurerm_network_security_group` resource and an `azurerm_subnet_network_security_group_association` to link the new NSG to the existing `data_subnet`, ensuring network traffic is filtered according to security policies."
}
